function phi = make_isoplanatic_phase(N, delta, corrLength, rmsValue, mask)
% MAKE_ISOPLANATIC_PHASE  Generate a realization of isoplanatic phase.
%   PHI = MAKE_ISOPLANATIC_PHASE(N, DELTA, CORRLENGTH, RMSVALUE, MASK)
%   generates an N-by-N realization of a zero-mean, spatially
%   stationary Gaussian random phase screen with a Gaussian
%   power spectral density of width CORRLENGTH, normalized to
%   RMS value RMSVALUE over the pupil support defined by MASK.
%
%   The phase is generated by filtering spatially white Gaussian noise
%   in the frequency domain with the square root of a Gaussian PSD:
%       G(fx, fy) = exp(-2*pi^2*corrLength^2*(fx^2 + fy^2))
%   then normalizing to rmsValue radians RMS over the pupil pixels.
%
%   Inputs:
%       N          - Grid size (N x N)
%       delta      - Sample spacing in the pupil plane [m]
%                    (typically D/N, where D is the pupil diameter)
%       corrLength - Phase correlation length [m]
%                    (typically D/10 for a moderately aberrated pupil)
%       rmsValue   - RMS phase error over the pupil [rad]
%       mask       - Binary pupil mask (1 inside pupil, 0 outside)
%
%   Output:
%       phi  - Isoplanatic phase screen [rad], N x N,
%              zero outside the pupil mask.
%
%   The random seed should be set before calling this function
%   (e.g., rng(1)) for reproducibility.
%
%   Reference: Eq. (8) and surrounding discussion in the chapter.

f       = ((0:N-1) - N/2) / (N * delta);   % frequency axes [cycles/m]
[fx,fy] = meshgrid(f, f);
G       = exp(-2 * pi^2 * corrLength^2 * (fx.^2 + fy.^2));

phi     = real(ifft2c(fft2c(randn(N)) .* G));

in  = mask > 0;
phi = rmsValue * (phi - mean(phi(in))) / std(phi(in));
phi = phi .* mask;
end
